import random
from typing import List

# Data type: arbitrary binary data
# Target stub uses FUZZ_PARAM_STR twice for buffers compared via memcmp, and a random unsigned int for n.
# We should return a single bytes buffer that the harness will split to provide those FUZZ_PARAM_STR/FUZZ_PARAM(unsigned int) calls.
# Strategy: Construct a compact corpus seed that includes two buffers A and B with varied lengths/content and a 32-bit n source.
# Layout:
# [u32 lenA][u32 lenB][u32 n_hint][lenA bytes A][lenB bytes B]
# Lengths are capped to keep total <= 4096.
# We fill A and B with patterns likely to exercise memcmp branches: all-equal, prefix-equal then differing byte, differing at start, random, and edge bytes.

MAX_TOTAL = 4096
MAX_SECTION = 1500  # practical cap per buffer to stay within total


def _u32(x: int) -> bytes:
    return x.to_bytes(4, 'little', signed=False)


def _pattern_bytes(kind: int, length: int, rng: random.Random) -> bytes:
    # kind selects pattern style
    if length <= 0:
        return b''
    if kind == 0:
        # all zeros
        return bytes([0]) * length
    if kind == 1:
        # all 0xFF
        return bytes([0xFF]) * length
    if kind == 2:
        # ascending bytes 0..255 wrap
        return bytes((i % 256 for i in range(length)))
    if kind == 3:
        # descending from 255
        return bytes(((255 - (i % 256)) for i in range(length)))
    if kind == 4:
        # repeated ASCII pattern with NULs interspersed
        base = b"FreeRTOS\x00memcmp\x00test\x00"
        out = bytearray()
        while len(out) < length:
            out.extend(base)
        return bytes(out[:length])
    if kind == 5:
        # random bytes
        return rng.randbytes(length)
    if kind == 6:
        # mostly same byte with occasional flip
        b = rng.randrange(256)
        out = bytearray([b] * length)
        flips = max(1, length // 16)
        for _ in range(flips):
            idx = rng.randrange(length)
            out[idx] = (out[idx] + 1) & 0xFF
        return bytes(out)
    # fallback random
    return rng.randbytes(length)


def _make_pair_with_relation(rng: random.Random, lenA: int, lenB: int):
    # Create A and B with interesting relationships for memcmp
    relation = rng.choice([
        'equal', 'diff_start', 'diff_end', 'prefix_equal_then_diff', 'random']
    )
    # ensure non-negative lengths
    lenA = max(0, lenA)
    lenB = max(0, lenB)

    if relation == 'equal':
        base_len = min(lenA, lenB)
        pat = _pattern_bytes(rng.randrange(7), base_len, rng)
        A = pat + (rng.randbytes(lenA - base_len) if lenA > base_len else b'')
        B = pat + (rng.randbytes(lenB - base_len) if lenB > base_len else b'')
        return A[:lenA], B[:lenB]

    if relation == 'diff_start':
        A = _pattern_bytes(rng.randrange(7), lenA, rng)
        B = bytearray(_pattern_bytes(rng.randrange(7), lenB, rng))
        if lenB > 0:
            B[0] = (B[0] + 1) & 0xFF
        return A, bytes(B)

    if relation == 'diff_end':
        A = _pattern_bytes(rng.randrange(7), lenA, rng)
        B = bytearray(_pattern_bytes(rng.randrange(7), lenB, rng))
        if lenB > 0:
            B[-1] = (B[-1] ^ 0x55) & 0xFF
        return A, bytes(B)

    if relation == 'prefix_equal_then_diff':
        common = rng.randrange(0, min(lenA, lenB) + 1) if (lenA and lenB) else 0
        prefix = _pattern_bytes(rng.randrange(7), common, rng)
        tailA = _pattern_bytes(rng.randrange(7), max(0, lenA - common), rng)
        tailB = bytearray(_pattern_bytes(rng.randrange(7), max(0, lenB - common), rng))
        if lenB - common > 0:
            idx = rng.randrange(lenB - common)
            tailB[idx] = (tailB[idx] + 1) & 0xFF
        return prefix + tailA, prefix + bytes(tailB)

    # random
    return _pattern_bytes(5, lenA, rng), _pattern_bytes(5, lenB, rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose lengths, include edge cases and random within cap
    candidates: List[int] = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64]
    lenA = rng.choice(candidates + [rng.randrange(0, MAX_SECTION + 1)])
    lenB = rng.choice(candidates + [rng.randrange(0, MAX_SECTION + 1)])

    # Ensure total within MAX_TOTAL including headers and n_hint
    header_size = 12
    max_payload = MAX_TOTAL - header_size
    # If too large, scale down proportionally
    total_len = lenA + lenB
    if total_len > max_payload:
        if total_len == 0:
            lenA = lenB = 0
        else:
            scale = max_payload / total_len
            lenA = int(lenA * scale)
            lenB = int(lenB * scale)

    # Build buffers with interesting relationships
    A, B = _make_pair_with_relation(rng, lenA, lenB)

    # Derive n_hint to encourage coverage:
    # sometimes 0, sometimes exactly min(lenA,lenB), sometimes within range, sometimes beyond (will be modded by fuzzer stub)
    maxN = min(len(A), len(B))
    n_options = [0]
    if maxN > 0:
        n_options.extend([1, maxN, max(0, maxN - 1), rng.randrange(0, maxN + 1)])
    # add a large number to test modulo behavior in stub
    n_options.append(0xFFFFFFFF)
    n_hint = rng.choice(n_options)

    out = bytearray()
    out += _u32(len(A))
    out += _u32(len(B))
    out += _u32(n_hint)
    out += A
    out += B
    return bytes(out)
